// Daily life outside careers and cultivation: the teen years, seasons and weather, food, illness and
// recovery, households and neighbours, money troubles and windfalls, festivals, home towns, tavern
// rumours (some of them true, and early), gambling, small kindnesses and cruelties, the heart-demon,
// and old age: failing bodies, last wishes and legacies.
import { E, O, C, R, P, M, Q, L, LATER } from './kit.js';
import { template } from '../../engine/registry.js';

// ── Template helpers ──────────────────────────────────────────────
// A row's first choice: a prebuilt choice (r.first), a chance (r.p) or a stat roll (r.stat, r.dc).
const roll = (r) => r.first || (r.p != null
  ? P(r.a, r.p, O(r.ok, r.okfx), O(r.no, r.nofx))
  : R(r.a, r.stat, r.dc, O(r.ok, r.okfx), O(r.no, r.nofx)));
const opt = (t, text, fx) => (t ? [C(t, O(text, fx))] : []);
const shape = (r) => [roll(r), ...opt(r.b, r.bt, r.bfx), ...opt(r.c, r.ct, r.cfx), ...(r.extra || [])];
// A paid choice: costs r.cost taels.
const paid = (r) => Q(r.b, { stat: { wealth: `>=${r.cost}` } }, O(r.bt, { wealth: -r.cost, ...r.bfx }));
// Merge a codex memory into an outcome's effects.
const mem = (id, fx = {}) => ({ ...fx, codex: [id, ...[].concat(fx.codex || [])] });

